using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;

namespace RingsideBooker.UI.Design
{
    /// <summary>
    /// The game's icon set: Lucide glyphs (ISC) as SVG path data in
    /// <c>Resources/Design/Icons.txt</c>, generated by <c>game/tools/icons/build-icons.mjs</c>.
    /// Screens use the game's names (<see cref="IconNames"/>), never Lucide's, so the set can change in
    /// one place.
    /// </summary>
    public static class IconLibrary
    {
        public const string ResourcePath = "Design/Icons";

        private static Dictionary<string, string> data;
        private static readonly Dictionary<string, SvgPath> Parsed = new Dictionary<string, SvgPath>();

        /// <summary>Every icon name in the set, in file order.</summary>
        public static IReadOnlyCollection<string> Names
        {
            get
            {
                Load();
                return data.Keys;
            }
        }

        public static bool Has(string name)
        {
            Load();
            return name != null && data.ContainsKey(name);
        }

        /// <summary>The parsed glyph, or null for an unknown name (logged once).</summary>
        public static SvgPath Get(string name)
        {
            if (name == null) return null;
            if (Parsed.TryGetValue(name, out SvgPath path)) return path;
            Load();
            if (!data.TryGetValue(name, out string d))
            {
                Debug.LogWarning($"[Icons] no icon named '{name}'");
                Parsed[name] = null;
                return null;
            }
            try
            {
                path = SvgPath.Parse(d);
            }
            catch (FormatException exception)
            {
                Debug.LogWarning($"[Icons] '{name}': {exception.Message}");
                path = null;
            }
            Parsed[name] = path;
            return path;
        }

        private static void Load()
        {
            if (data != null) return;
            data = new Dictionary<string, string>();
            var asset = Resources.Load<TextAsset>(ResourcePath);
            if (asset == null)
            {
                Debug.LogError($"[Icons] missing Resources/{ResourcePath}.txt");
                return;
            }
            foreach (string line in asset.text.Split('\n'))
            {
                if (line.Length == 0 || line[0] == '#') continue;
                int tab = line.IndexOf('\t');
                if (tab > 0) data[line.Substring(0, tab)] = line.Substring(tab + 1).Trim();
            }
        }
    }

    /// <summary>The icon names screens use (a subset; <see cref="IconLibrary.Names"/> has them all).</summary>
    public static class IconNames
    {
        public const string Office = "office";
        public const string Roster = "roster";
        public const string Booking = "booking";
        public const string Calendar = "calendar";
        public const string Titles = "titles";
        public const string Why = "why";
        public const string Warning = "warning";
        public const string Problem = "problem";
        public const string Check = "check";
        public const string Live = "live";
        public const string Close = "close";
        public const string Columns = "columns";
        public const string Filter = "filter";
        public const string Search = "search";
        public const string ChevronDown = "chevron-down";
        public const string ChevronRight = "chevron-right";
        public const string Star = "star";
        public const string Versus = "versus";
    }

    /// <summary>
    /// One icon, stroked like the web's Lucide icons (2px on a 24px grid, round caps) in the element's
    /// text <c>color</c>, so hover and state colours apply as they do to labels. Size it with the
    /// <c>ds-icon--*</c> classes (or width/height). <see cref="Filled"/> fills the shape instead (stars).
    /// </summary>
    public sealed class Icon : VisualElement
    {
        public const string UssClass = "ds-icon";

        private static readonly CustomStyleProperty<float> StrokeProperty = new CustomStyleProperty<float>("--icon-stroke");

        private string iconName;
        private bool filled;
        private float stroke = 2f;

        public Icon() : this(null)
        {
        }

        public Icon(string name, params string[] classes)
        {
            AddToClassList(UssClass);
            foreach (string className in classes) AddToClassList(className);
            pickingMode = PickingMode.Ignore;
            iconName = name;
            generateVisualContent += Draw;
            RegisterCallback<CustomStyleResolvedEvent>(OnStyle);
        }

        public string Glyph
        {
            get => iconName;
            set
            {
                if (iconName == value) return;
                iconName = value;
                MarkDirtyRepaint();
            }
        }

        /// <summary>Fills the glyph's closed shapes (a filled star) instead of stroking it.</summary>
        public bool Filled
        {
            get => filled;
            set
            {
                filled = value;
                MarkDirtyRepaint();
            }
        }

        private void OnStyle(CustomStyleResolvedEvent evt)
        {
            if (evt.customStyle.TryGetValue(StrokeProperty, out float value)) stroke = value;
            MarkDirtyRepaint();
        }

        private void Draw(MeshGenerationContext context)
        {
            SvgPath path = IconLibrary.Get(iconName);
            Rect box = contentRect;
            if (path == null || box.width <= 0 || box.height <= 0) return;

            float size = Mathf.Min(box.width, box.height);
            float scale = size / 24f;
            var offset = new Vector2(box.x + (box.width - size) / 2f, box.y + (box.height - size) / 2f);
            Color color = resolvedStyle.color;

            Painter2D painter = context.painter2D;
            painter.BeginPath();
            path.AddTo(painter, scale, offset);
            if (filled)
            {
                painter.fillColor = color;
                painter.Fill(FillRule.NonZero);
            }
            else
            {
                painter.lineWidth = Mathf.Max(1f, stroke * scale);
                painter.lineCap = LineCap.Round;
                painter.lineJoin = LineJoin.Round;
                painter.strokeColor = color;
                painter.Stroke();
            }
        }
    }
}
